import gurobipy as gp
import pandas as pd
import numpy as np
import sys
import re

try:
    # 1. Load data
    df = pd.read_csv('/inputs/43.csv')

    # 2. Identify product and equipment sets
    # Products
    products = ['Product I', 'Product II', 'Product III']
    product_short = {'Product I': 'I', 'Product II': 'II', 'Product III': 'III'}
    # Procedures
    procedures = ['A', 'B']
    # Equipment for A and B (from problem statement)
    E_A = ['A1', 'A2']
    E_B = ['B1', 'B2', 'B3']
    # All equipment (from data, but only those relevant for A/B)
    equipment_rows = df['Equipment / Cost'].tolist()
    # Remove summary/cost rows
    equipment_rows = [e for e in equipment_rows if e not in [
        'Raw Material Cost (yuan/unit)', 'Unit Price (yuan/unit)']]
    # Only keep A1, A2, B1, B2, B3 (ignore A3, B4 as not eligible for any product/procedure)
    E = [e for e in equipment_rows if e in E_A + E_B]

    # 3. Extract parameters
    # Processing time per unit: t_{e,p}
    t = {}  # (e,p): time per unit
    for idx, row in df.iterrows():
        e = row['Equipment / Cost']
        if e in E:
            for p in products:
                val = row[p]
                if pd.notnull(val) and str(val).strip() != '':
                    t[(e, p)] = float(val)

    # Available equipment operating time: T_e
    T = {}
    for idx, row in df.iterrows():
        e = row['Equipment / Cost']
        if e in E:
            val = row['Available Equipment Operating Time']
            if pd.notnull(val) and str(val).strip() != '':
                T[e] = float(val)

    # Equipment cost at full load: C_e
    C = {}
    for idx, row in df.iterrows():
        e = row['Equipment / Cost']
        if e in E:
            val = row['Equipment Cost at Full Load (yuan)']
            if pd.notnull(val) and str(val).strip() != '':
                C[e] = float(val)

    # Raw material cost per unit: c_raw_p
    c_raw = {}
    row_raw = df[df['Equipment / Cost'] == 'Raw Material Cost (yuan/unit)']
    if row_raw.empty:
        raise KeyError("Missing 'Raw Material Cost (yuan/unit)' row in 43.csv")
    for p in products:
        val = row_raw.iloc[0][p]
        if pd.notnull(val) and str(val).strip() != '':
            c_raw[p] = float(val)
        else:
            raise KeyError(f"Missing raw material cost for {p}")

    # Selling price per unit: r_p
    r = {}
    row_price = df[df['Equipment / Cost'] == 'Unit Price (yuan/unit)']
    if row_price.empty:
        raise KeyError("Missing 'Unit Price (yuan/unit)' row in 43.csv")
    for p in products:
        val = row_price.iloc[0][p]
        if pd.notnull(val) and str(val).strip() != '':
            r[p] = float(val)
        else:
            raise KeyError(f"Missing unit price for {p}")

    # 4. Equipment eligibility
    # For each (product, procedure), list eligible equipment
    E_p_s = {}
    # Procedure A
    E_p_s[('Product I', 'A')] = ['A1', 'A2']
    E_p_s[('Product II', 'A')] = ['A1', 'A2']
    E_p_s[('Product III', 'A')] = ['A2']
    # Procedure B
    E_p_s[('Product I', 'B')] = ['B1', 'B2', 'B3']
    E_p_s[('Product II', 'B')] = ['B1']
    E_p_s[('Product III', 'B')] = ['B2']

    # For each equipment, which products/procedures can it process?
    E_proc = {}
    for e in E:
        E_proc[e] = []
        for p in products:
            for s in procedures:
                if e in E_p_s.get((p, s), []):
                    E_proc[e].append((p, s))

    # 5. Model
    m = gp.Model('FactoryProductionPlan')

    # Decision variables:
    # x_p: total production quantity of product p
    x = m.addVars(products, lb=0.0, name='x')

    # x_{e,p,s}: quantity of product p processed on equipment e in procedure s (only for eligible (e,p,s))
    x_eps = {}
    for p in products:
        for s in procedures:
            for e in E_p_s.get((p, s), []):
                x_eps[(e, p, s)] = m.addVar(lb=0.0, name=f"x_{e}_{product_short[p]}_{s}")

    # 6. Constraints

    # a) Production assignment for each product and procedure
    for p in products:
        # For procedure A
        m.addConstr(
            x[p] == gp.quicksum(x_eps[(e, p, 'A')] for e in E_p_s[(p, 'A')]),
            name=f"assign_A_{product_short[p]}"
        )
        # For procedure B
        m.addConstr(
            x[p] == gp.quicksum(x_eps[(e, p, 'B')] for e in E_p_s[(p, 'B')]),
            name=f"assign_B_{product_short[p]}"
        )

    # b) Equipment time capacity
    for e in E:
        # For all (p,s) that can be processed on e
        m.addConstr(
            gp.quicksum(
                t[(e, p)] * x_eps[(e, p, s)]
                for (p, s) in E_proc[e]
            ) <= T[e],
            name=f"timecap_{e}"
        )

    # c) Consistency between procedures (already enforced by assignment constraints above)

    # d) Non-negativity: handled by variable domains

    # 7. Objective function
    # Maximize total profit:
    # sum_p r_p x_p - sum_p c_raw_p x_p - sum_e (C_e / T_e) * sum_{(p,s) in E_proc[e]} t_{e,p} * x_{e,p,s}
    revenue = gp.quicksum(r[p] * x[p] for p in products)
    raw_cost = gp.quicksum(c_raw[p] * x[p] for p in products)
    equip_cost = gp.quicksum(
        (C[e] / T[e]) * gp.quicksum(
            t[(e, p)] * x_eps[(e, p, s)]
            for (p, s) in E_proc[e]
        )
        for e in E
    )
    m.setObjective(revenue - raw_cost - equip_cost, gp.GRB.MAXIMIZE)

    # 8. Optimize
    m.optimize()

except KeyError as e:
    print(f"Data Error: A required column was not found. {e}", file=sys.stderr)
except pd.errors.EmptyDataError as e:
    print(f"Data Error: CSV file is empty or unreadable. {e}", file=sys.stderr)
except Exception as e:
    print(f"An unexpected error occurred: {e}", file=sys.stderr)
